<?php require "../config.php";require_role("admin");if(isset($_GET["id"],$_GET["status"])&&in_array($_GET["status"],["Pending","Approved","Rejected"])){$s=$conn->prepare("UPDATE applications SET status=? WHERE id=?");$s->bind_param("si",$_GET["status"],$_GET["id"]);$s->execute();}$rows=$conn->query("SELECT a.*,p.name program FROM applications a JOIN programs p ON p.id=a.program_id ORDER BY a.id DESC");$page_title="Admissions";require "../includes/header.php";?><section class="portal-shell pb-5"><div class="container"><h1 class="section-title">Admissions</h1><div class="table-wrap mt-4"><table class="table"><tr><th>Applicant</th><th>Program</th><th>Status</th><th>Action</th></tr><?php while($a=$rows->fetch_assoc()):?><tr><td><?=e($a["name"])?><br><?=e($a["email"])?></td><td><?=e($a["program"])?></td><td><?=e($a["status"])?></td><td><a class="btn btn-sm btn-success" href="?id=<?=$a["id"]?>&status=Approved">Approve</a> <a class="btn btn-sm btn-outline-danger" href="?id=<?=$a["id"]?>&status=Rejected">Reject</a></td></tr><?php endwhile;?></table></div></div></section><?php require "../includes/footer.php";?>